### POINT SOURCE POINT LENS (PSPL) CLASSES ###
######################################################
# --------------------------------------------------
#
# Data Class Family
#
# --------------------------------------------------
class PSPL(ABC):
    def _parallax_vectors_for_jax(self, t, filt_idx=0):
        """
        Precompute host-side parallax direction table for JAX kernels.

        Parameters
        ----------
        t : array_like
            Observation times in MJD.
        filt_idx : int, optional
            Index into ``obsLocation`` when it is per-filter.

        Returns
        -------
        parallax_vectors : ndarray or None
            Shape ``(N_times, 2)`` East/North AU table, or ``None`` when
            parallax is disabled.
        """
        if self.parallaxFlag is False:
            return None

        # Observer location may be a single string or per-filter list.
        obs = self.obsLocation
        if isinstance(obs, (list, tuple, np.ndarray)):
            obs_loc = obs[filt_idx]
        else:
            obs_loc = obs

        # Host ephemeris table; not differentiated inside JAX.
        parallax_vectors = jax_physics.precompute_parallax_vectors(
            float(self.raL), float(self.decL), t, obs_location=str(obs_loc)
        )

        return parallax_vectors

    def _phot_scalar(self, phot_param_name, filt_idx=0, default=None):
        """
        Return a scalar photometry parameter for filter ``filt_idx``.

        Parameters
        ----------
        phot_param_name : str
            Attribute name on ``self`` (e.g. ``'b_sff'``, ``'mag_src'``).
        filt_idx : int, optional
            Photometric filter index.
        default : float or None, optional
            Value returned when the attribute is missing or empty.

        Returns
        -------
        param_val : float or None
            Scalar parameter for the requested filter.
        """
        val = getattr(self, phot_param_name, None)
        if val is None:
            return default

        arr = np.asarray(val).reshape(-1)
        if arr.size == 0:
            return default

        # Prefer the requested filter; fall back to the first entry.
        param_val = float(arr[filt_idx]) if arr.size > filt_idx else float(arr[0])

        return param_val

    def _mag_src_for_jax(self, filt_idx=0):
        """
        Source magnitude for JAX photometry (handles ``mag_base`` layouts).

        Parameters
        ----------
        filt_idx : int, optional
            Photometric filter index.

        Returns
        -------
        mag_src : float or None
            Unlensed source magnitude, or ``None`` if unavailable.
        """
        mag_src = self._phot_scalar("mag_src", filt_idx)
        if mag_src is not None:
            return mag_src

        # Param2-style layouts store mag_base; convert with b_sff.
        mag_base = self._phot_scalar("mag_base", filt_idx)
        b_sff = self._phot_scalar("b_sff", filt_idx)
        if mag_base is None or b_sff is None:
            return None

        mag_src = float(mag_base - 2.5 * np.log10(b_sff))

        return mag_src

    def get_lens_astrometry(self, t, filt_idx=0):
        """
        Get the astrometry for the foreground lens at the input times.
        The returned array is in arcsec and has a shape of [len(t), 2]
        where the second dimension includes [RA, Dec] positions in arcsec.

        Parameters
        ----------
        t : array_like
            Time (in MJD).
        filt_idx : int, optional
            Index of the astrometric filter or data set.

        Returns
        -------
        xL : array_like, dtype=float, shape = [len(t), 2]
            Position of the lens on the sky (arcsec).
        """
        t_j = jnp.asarray(t, dtype=jnp.float64).reshape(-1)

        # Phot-only models have no absolute lens sky track.
        # Return 0 for their positions at all times.
        if not hasattr(self, "xL0") or self.xL0 is None:
            return np.zeros((int(t_j.shape[0]), 2), dtype=np.float64)

        # Parallax table and optional lens parallax amplitude.
        pvec = self._parallax_vectors_for_jax(t, filt_idx)
        piL = getattr(self, "piL", None)

        xL = jax_physics.pspl_linear_astrometry(
            t_j,
            jnp.asarray(self.t0, dtype=jnp.float64),
            jnp.asarray(
                self.xL0[filt_idx],
                dtype=jnp.float64,
            ),
            jnp.asarray(self.muL, dtype=jnp.float64),
            parallax_vectors=pvec,
            pi=None if piL is None else jnp.asarray(piL, dtype=jnp.float64),
            pi_ref=None if not self.ref_frame_parallax_flag else jnp.asarray(
                self.pi_ref_frame[filt_idx], dtype=jnp.float64
            ),
        )

        return np.asarray(xL, dtype=np.float64)

    def get_source_astrometry_unlensed(self, t, filt_idx=0):
        """
        Get the astrometry of the source if the lens didn't exist.
        The returned array is in arcsec and has a shape of [len(t), 2]
        where the second dimension includes [RA, Dec] positions in arcsec.

        Parameters
        ----------
        t : array_like
            Time (in MJD).
        filt_idx : int, optional
            Index of the astrometric filter or data set.

        Returns
        -------
        xS_unlensed : numpy array, dtype=float, shape = [len(t), 2]
            The unlensed positions of the source in arcseconds.
        """
        pvec = self._parallax_vectors_for_jax(t, filt_idx)
        pi_s = getattr(self, "piS", None)

        xS_unlensed = jax_physics.pspl_source_astrometry_unlensed(
            jnp.asarray(t, dtype=jnp.float64).reshape(-1),
            jnp.asarray(self.t0, dtype=jnp.float64),
            jnp.asarray(
                self.xS0[filt_idx],
                dtype=jnp.float64,
            ),
            jnp.asarray(self.muS, dtype=jnp.float64),
            parallax_vectors=pvec,
            piS=None if pi_s is None else jnp.asarray(pi_s, dtype=jnp.float64),
            pi_ref=None if not self.ref_frame_parallax_flag else jnp.asarray(
                self.pi_ref_frame[filt_idx], dtype=jnp.float64
            ),
        )

        return np.asarray(xS_unlensed, dtype=np.float64)

    def get_astrometry_unlensed(self, t, filt_idx=0):
        """
        Get the unresolved astrometry of the combined source and lens if
        there was no gravitational lensing. The returned array is in
        arcsec and has a shape of [len(t), 2] where the second dimension
        includes [RA, Dec] positions in arcsec.

        Parameters
        ----------
        t : array_like
            Time (in MJD).
        filt_idx : int, optional
            Index of the astrometric filter or data set.

        Returns
        -------
        xS_unlensed : numpy array, dtype=float, shape = [len(t), 2]
            The unlensed, flux-weighted centroid position of the source+lens in arcseconds.
        """
        # Phot-only path: Einstein-radius centroid with blend on the lens.
        if not hasattr(self, "xS0") or self.xS0 is None:
            pvec = self._parallax_vectors_for_jax(t, filt_idx)
            b_sff = self._phot_scalar("b_sff", filt_idx, default=1.0)
            u_cent = jax_physics.pspl_phot_astrometry_unlensed(
                jnp.asarray(t, dtype=jnp.float64).reshape(-1),
                jnp.asarray(self.t0, dtype=jnp.float64),
                jnp.asarray(self.tE, dtype=jnp.float64),
                jnp.asarray(self.u0, dtype=jnp.float64),
                jnp.asarray(self.thetaE_hat, dtype=jnp.float64),
                b_sff,
                parallax_vectors=pvec,
                piE_E=jnp.asarray(self.piE[0], dtype=jnp.float64),
                piE_N=jnp.asarray(self.piE[1], dtype=jnp.float64),
            )
            return np.asarray(u_cent, dtype=np.float64)

        # PhotAstrom path: blend absolute source and lens sky tracks.
        # Clip a negative lens flux (b_sff > 1) so the lens is dark.
        xS_unlensed = self.get_source_astrometry_unlensed(t, filt_idx=filt_idx)
        xL_unlensed = self.get_lens_astrometry(t, filt_idx=filt_idx)
        b_sff = self._phot_scalar("b_sff", filt_idx, default=1.0)
        src_flux_frac = astrometric_source_flux_fraction(b_sff)
        pos_unlensed = src_flux_frac * xS_unlensed + (1.0 - src_flux_frac) * xL_unlensed

        return pos_unlensed

    def get_all_arrays(self, t, filt_idx=0):
        """
        Positions and amplifications of the plus and minus images.

        Parameters
        ----------
        t : array_like
            Array of times in MJD.DDD
        filt_idx : int, optional
            Index of the photometric or astrometric filter or data set.

        Returns
        -------
        images : numpy array, dtype=complex, shape = [len(t), N_sources=1, [+, -]]
            Image positions, East + i North, matching
            :meth:`get_resolved_astrometry`: arcsec on the sky for
            astrometric models, Einstein radii from the lens otherwise.
        amps : numpy array, dtype=float, shape = [len(t), N_sources=1, [+, -]]
            Amplification of each image.
        """
        # Shape of u_vec: [N_times, 2]
        u_vec = np.asarray(self.get_u(t, filt_idx=filt_idx), dtype=np.float64)
        u_amp = np.linalg.norm(u_vec, axis=1)
        sqrt_term = np.sqrt(u_amp ** 2 + 4)

        # Image positions in the get_resolved_astrometry frame: arcsec on the
        # sky for astrometric models, Einstein radii from the lens otherwise.
        xS_res = np.asarray(self.get_resolved_astrometry(t, filt_idx=filt_idx),
                            dtype=np.float64)
        images = xS_res[..., 0] + 1j * xS_res[..., 1]

        # Image amplifications from the JAX kernel.
        a_plus, a_minus = jax_physics.pspl_resolved_amplification_from_u(
            jnp.asarray(u_vec, dtype=jnp.float64))
        amps = np.zeros((len(u_amp), 1, 2), dtype=np.float64)
        amps[:, 0, 0] = np.asarray(a_plus)
        amps[:, 0, 1] = np.asarray(a_minus)

        return images, amps

    def _source_fluxes(self, filt_idx=0):
        """
        Unlensed flux of each source in one filter.

        Parameters
        ----------
        filt_idx : int, optional
            Index of the photometric filter or data set.

        Returns
        -------
        flux_src : numpy array, shape = [N_sources]
            One entry for single-source models, [primary, secondary] for
            binary sources.
        """
        if hasattr(self, 'mag_src_pri'):
            mags = [self.mag_src_pri[filt_idx], self.mag_src_sec[filt_idx]]
        else:
            mags = [self.mag_src[filt_idx]]

        return np.array([mag2flux(m) for m in mags], dtype=np.float64)

    def get_resolved_amplification(self, t, filt_idx=0, amp_arr=None):
        """
        Get the photometric amplification of each lensed image.

        Parameters
        ----------
        t : array_like
            Array of times in MJD.DDD
        filt_idx : int, optional
            Index of the astrometric filter or data set.
        amp_arr : array_like, optional
            Amplifications from :meth:`get_all_arrays`; overrides ``t``.

        Returns
        -------
        A : numpy array, dtype=float, shape = [len(t), N_sources, N_images]
            The amplification of each lensed image (NaN for missing images).
        """
        if amp_arr is None:
            _img, amp_arr = self.get_all_arrays(t, filt_idx=filt_idx)

        return np.array(amp_arr, dtype=np.float64)

    def get_resolved_photometry(self, t, filt_idx=0, amp_arr=None):
        """
        Get the magnitude of each lensed source image.

        The magnitudes contain only the lensed source flux. The blend flux
        (neighbors and lenses) is not included, so the image fluxes plus the
        blend flux give :meth:`get_photometry`.

        Parameters
        ----------
        t : array_like
            Array of times in MJD.DDD
        filt_idx : int, optional
            Index of the photometric filter or data set.
        amp_arr : array_like, optional
            Amplifications from :meth:`get_all_arrays`; overrides ``t``.

        Returns
        -------
        mag_model : numpy array, dtype=float, shape = [len(t), N_sources, N_images]
            Magnitude of each image; NaN for missing images or non-positive
            flux.
        """
        amp = self.get_resolved_amplification(t, filt_idx=filt_idx, amp_arr=amp_arr)

        # Lensed flux of each image: source flux times image amplification.
        flux_src = self._source_fluxes(filt_idx)
        flux_model = amp * flux_src[np.newaxis, :, np.newaxis]

        # Magnitudes only exist for positive flux.
        flux_model = np.where(flux_model > 0, flux_model, np.nan)
        with np.errstate(invalid='ignore'):
            mag_model = flux2mag(flux_model)

        return mag_model

    def get_amplification(self, t, filt_idx=0):
        """
        Get an array of the total photometric amplifications at the input times.

        Parameters
        ----------
        t : array_like
            Array of times in MJD.DDD
        filt_idx : int, optional
            Index of the astrometric filter or data set.

        Returns
        -------
        A : numpy array, dtype=float, shape = [len(t)]
            The total amplification (sum of +/- images)
        """
        pvec = self._parallax_vectors_for_jax(t, filt_idx)

        amp = jax_physics.pspl_amplification(
            jnp.asarray(t, dtype=jnp.float64).reshape(-1),
            jnp.asarray(self.t0, dtype=jnp.float64),
            jnp.asarray(self.tE, dtype=jnp.float64),
            jnp.asarray(self.u0, dtype=jnp.float64),
            jnp.asarray(self.thetaE_hat, dtype=jnp.float64),
            parallax_vectors=pvec,
            piE_E=jnp.asarray(self.piE[0], dtype=jnp.float64),
            piE_N=jnp.asarray(self.piE[1], dtype=jnp.float64),
        )

        return np.asarray(amp, dtype=np.float64)

    def get_resolved_astrometry(self, t, filt_idx=0):
        """
        Get the RA and Dec astrometry of the plus and minus source images.

        Parameters
        ----------
        t : array_like
            Time (in MJD).
        filt_idx : int, optional
            Index of the astrometric filter or data set.

        Returns
        -------
        xS_res : numpy array, shape = [len(t), N_sources=1, [+, -], [E, N]]
            Sky positions of the plus and minus images in arcsec.
        """
        pvec = self._parallax_vectors_for_jax(t, filt_idx)

        pos_images = jax_physics.pspl_resolved_astrometry(
            jnp.asarray(t, dtype=jnp.float64).reshape(-1),
            jnp.asarray(self.t0, dtype=jnp.float64),
            jnp.asarray(self.tE, dtype=jnp.float64),
            jnp.asarray(self.u0, dtype=jnp.float64),
            jnp.asarray(self.thetaE_hat, dtype=jnp.float64),
            jnp.asarray(
                self.xL0[filt_idx],
                dtype=jnp.float64,
            ),
            jnp.asarray(self.muL, dtype=jnp.float64),
            jnp.asarray(self.thetaE_amp, dtype=jnp.float64),
            parallax_vectors=pvec,
            piE_E=jnp.asarray(self.piE[0], dtype=jnp.float64),
            piE_N=jnp.asarray(self.piE[1], dtype=jnp.float64),
            piL=jnp.asarray(self.piL, dtype=jnp.float64),
            pi_ref=None if not self.ref_frame_parallax_flag else jnp.asarray(
                self.pi_ref_frame[filt_idx], dtype=jnp.float64
            ),
        )

        # Kernel layout [[+, -], N_times, 2] -> [N_times, 1, [+, -], 2].
        xS_res = np.swapaxes(np.asarray(pos_images, dtype=np.float64), 0, 1)
        xS_res = xS_res[:, np.newaxis]

        return xS_res

    def get_astrometry(self, t, filt_idx=0):
        """
        Get the astrometry of the unresolved (observed) position of the
        lensed source at the input times. The returned array is in arcsec and
        has a shape of [len(t), 2] where the second dimension includes
        [RA, Dec] positions in arcsec.

        Parameters
        ----------
        t : array_like
            Time (in MJD).
        filt_idx : int, optional
            Index of the astrometric filter or data set.

        Returns
        -------
        centroid : numpy array, dtype=float, shape = [len(t), 2]
            The flux-weighted centroid of all lensed images from the source and
            any luminous lenses.

        """
        t_j = jnp.asarray(t, dtype=jnp.float64).reshape(-1)
        pvec = self._parallax_vectors_for_jax(t, filt_idx)
        b_sff = self._phot_scalar("b_sff", filt_idx, default=1.0)

        # Phot-only: Einstein-radius flux-weighted centroid.
        if not hasattr(self, "xS0") or self.xS0 is None:
            mag_src = self._mag_src_for_jax(filt_idx)
            u_cent = jax_physics.pspl_phot_astrometry(
                t_j,
                jnp.asarray(self.t0, dtype=jnp.float64),
                jnp.asarray(self.tE, dtype=jnp.float64),
                jnp.asarray(self.u0, dtype=jnp.float64),
                jnp.asarray(self.thetaE_hat, dtype=jnp.float64),
                mag_src,
                b_sff,
                parallax_vectors=pvec,
                piE_E=jnp.asarray(self.piE[0], dtype=jnp.float64),
                piE_N=jnp.asarray(self.piE[1], dtype=jnp.float64),
            )
            return np.asarray(u_cent, dtype=np.float64)

        # PhotAstrom: absolute sky centroid with luminous lens blend.
        centroid = jax_physics.pspl_astrometry_param1(
            t_j,
            jnp.asarray(self.t0, dtype=jnp.float64),
            jnp.asarray(
                self.xS0[filt_idx],
                dtype=jnp.float64,
            ),
            jnp.asarray(
                self.xL0[filt_idx],
                dtype=jnp.float64,
            ),
            jnp.asarray(self.muS, dtype=jnp.float64),
            jnp.asarray(self.muL, dtype=jnp.float64),
            jnp.asarray(self.thetaE_amp, dtype=jnp.float64),
            b_sff,
            parallax_vectors=pvec,
            piS=jnp.asarray(self.piS, dtype=jnp.float64),
            piL=jnp.asarray(self.piL, dtype=jnp.float64),
            pi_ref=None if not self.ref_frame_parallax_flag else jnp.asarray(
                self.pi_ref_frame[filt_idx], dtype=jnp.float64
            ),
        )

        return np.asarray(centroid, dtype=np.float64)

    def get_photometry(self, t, filt_idx=0):
        """
        Get the predicted photomety at the specified times for the specified
        photometric filter or data set.

        Parameters
        ----------
        t : array_like
            List of times in MJD for the observations.
        filt_idx : int, optional
            Index of the photometric filter or data set.

        Returns
        -------
        mag_model : array_like
            Magnitude of the unresolved microlensing event at t.

        """
        mag_src = self._mag_src_for_jax(filt_idx)
        if mag_src is None:
            raise AttributeError("Model needs mag_src or mag_base for photometry")

        b_sff = self._phot_scalar("b_sff", filt_idx)
        pvec = self._parallax_vectors_for_jax(t, filt_idx)

        mag_model = jax_physics.pspl_photometry(
            jnp.asarray(t, dtype=jnp.float64).reshape(-1),
            jnp.asarray(self.t0, dtype=jnp.float64),
            jnp.asarray(self.tE, dtype=jnp.float64),
            jnp.asarray(self.u0, dtype=jnp.float64),
            jnp.asarray(self.thetaE_hat, dtype=jnp.float64),
            mag_src,
            b_sff=b_sff,
            parallax_vectors=pvec,
            piE_E=jnp.asarray(self.piE[0], dtype=jnp.float64),
            piE_N=jnp.asarray(self.piE[1], dtype=jnp.float64),
        )

        return np.asarray(mag_model, dtype=np.float64)

    def get_centroid_shift(self, t, filt_idx=0):
        """
        Get the centroid shift (in mas) at the input times. The centroid shift
        is the difference between the
        lensed, unresolved position (with lensed source + lens light) and the
        unlensed, unresolved position (with unlensed source + lens light).
        The returned array is in arcsec and has a shape of [len(t), 2] where
        the second dimension includes [RA, Dec] positions in arcsec.

        Parameters
        ----------
        t : array_like
            Time (in MJD).
        filt_idx : int, optional
            Index of the photometric filter or data set.

        Returns
        -------
        shift : numpy array, dtype=float, shape = [len(t), 2]
            Centroid shift in milliarcseconds.
        """
        # Lensed and unlensed unresolved centroids (arcsec).
        ast = self.get_astrometry(t, filt_idx=filt_idx)
        unl = self.get_astrometry_unlensed(t, filt_idx=filt_idx)

        # Convert arcsec difference to mas.
        shift = (np.asarray(ast) - np.asarray(unl)) * 1e3

        return shift

    def get_u(self, t, filt_idx=0):
        """
        Get the unlensed, relative astrometry of the source and lens in units
        of the Einstein radius.

        Parameters
        ----------
        t : array_like
            List of times in MJD for the observations.
        filt_idx : int, optional
            Index of the photometric filter or data set.

        Returns
        -------
        u_unlensed : numpy array, dtype=float, ``shape = len(t) x 2``
            The unlensed positions of the source in Einstein radii.
        """
        pvec = self._parallax_vectors_for_jax(t, filt_idx)

        u = jax_physics.pspl_u(
            jnp.asarray(t, dtype=jnp.float64).reshape(-1),
            jnp.asarray(self.t0, dtype=jnp.float64),
            jnp.asarray(self.tE, dtype=jnp.float64),
            jnp.asarray(self.u0, dtype=jnp.float64),
            jnp.asarray(self.thetaE_hat, dtype=jnp.float64),
            parallax_vectors=pvec,
            piE_E=jnp.asarray(self.piE[0], dtype=jnp.float64),
            piE_N=jnp.asarray(self.piE[1], dtype=jnp.float64),
        )

        return np.asarray(u, dtype=np.float64)

    def get_chi2_photometry(self, t, mag_obs, mag_err_obs, filt_idx=0):
        """
        Get chi^2 values for the model and input photometric data in the
        specified photometric filter or data set.

        Parameters
        ----------
        t : array_like
            List of times in MJD for the observations.
        mag_obs : array_like
            List of observed photometric measurements of the microlensing event in magnitudes.
            Length must be the same as t.
        mag_err_obs : array_like
            List of observed photometric uncertainties of the microlensing event in magnitudes.
            Length must be the same as t.
        filt_idx : int, optional
            Index of the photometric filter or data set.

        Returns
        -------
        chi2 : array_like
            List of chi^2 values from the model and photometric data.

        """
        mag_model = self.get_photometry(t, filt_idx=filt_idx)

        chi2 = jax_physics.gaussian_chi2_photometry(
            jnp.asarray(mag_model, dtype=jnp.float64),
            jnp.asarray(mag_obs, dtype=jnp.float64),
            jnp.asarray(mag_err_obs, dtype=jnp.float64),
        )

        return np.asarray(chi2, dtype=np.float64)

    def get_chi2_astrometry(self, t, x_obs, y_obs, x_err_obs, y_err_obs, filt_idx=0):
        """
        Get the chi^2 value for this model given input astrometry data and
        uncertainties for the specified astrometric data set.

        Parameters
        ----------
        t : array_like
            List of times in MJD for the observations.
        x_obs : array_like
            List of relative R.A. astrometric positions on the sky in arcsec.
            Length must match t.
        y_obs : array_like
            List of relative Dec. astrometric positions on the sky in arcsec.
            Length must match t.
        x_err_obs : array_like
            List of relative R.A. astrometric positional errors on the sky in arcsec.
            Length must match t.
        y_err_obs : array_like
            List of relative Dec. astrometric positional errors on the sky in arcsec.
            Length must match t.
        filt_idx : int, optional
            The index of the astrometric filter or data set.

        Returns
        -------
        chi2 : array_like
            List of chi^2 values from the model and astrometric data.

        """
        pos_model = self.get_astrometry(t, filt_idx=filt_idx)

        chi2 = jax_physics.gaussian_chi2_astrometry(
            jnp.asarray(pos_model, dtype=jnp.float64),
            jnp.asarray(x_obs, dtype=jnp.float64),
            jnp.asarray(y_obs, dtype=jnp.float64),
            jnp.asarray(x_err_obs, dtype=jnp.float64),
            jnp.asarray(y_err_obs, dtype=jnp.float64),
        )

        return np.asarray(chi2, dtype=np.float64)

    def get_lnL_constant(self, err_obs):
        """
        Get the natural log of the constant normalization terms of the likelihood.

        .. math:: -0.5 * \\ln{2 \\pi \\sigma_{obs}^2}

        Parameters
        ----------
        err_obs : array_like
            List of the uncertainties.

        Returns
        -------
        lnL_const : array_like
            List of ln(likelihood constants).

        """
        lnL_const = -0.5 * np.log(2.0 * math.pi * err_obs ** 2)

        return lnL_const

    def log_likely_photometry_each(self, t, mag_obs, mag_err_obs, filt_idx=0):
        """
        Get the natural log of the likelihood for the input photometric data in the
        specified filter or data sets. Note, this function returns a list and it
        is the full ln(likelihood), including the normalization constant.

        Parameters
        ----------
        t : array_like
            List of times in MJD for the observations.
        mag_obs : array_like
            List of observed photometric measurements of the microlensing event in magnitudes.
            Length must be the same as t.
        mag_err_obs : array_like
            List of observed photometric uncertainties of the microlensing event in magnitudes.
            Length must be the same as t.
        filt_idx : int, optional
            Index of the photometric filter or data set.

        Returns
        -------
        ln_L : array_like
            List of ln(likelihood) for each photometric measurement.

        """
        mag_model = self.get_photometry(t, filt_idx=filt_idx)

        lnL = jax_physics.gaussian_log_likelihood_photometry_each(
            jnp.asarray(mag_model, dtype=jnp.float64),
            jnp.asarray(mag_obs, dtype=jnp.float64),
            jnp.asarray(mag_err_obs, dtype=jnp.float64),
        )

        return np.asarray(lnL, dtype=np.float64)

    def log_likely_photometry(self, t, mag_obs, mag_err_obs, filt_idx=0):
        """
        Get the summed natural log of the likelihood for the input photometric data for the
        specified filter or data set. Note, this function returns the full ln(likelihood),
        including the normalization constant.

        Parameters
        ----------
        t : array_like
            List of times in MJD for the observations.
        mag_obs : array_like
            List of observed photometric measurements of the microlensing event in magnitudes.
            Length must be the same as t.
        mag_err_obs : array_like
            List of observed photometric uncertainties of the microlensing event in magnitudes.
            Length must be the same as t.
        filt_idx : int, optional
            Index of the photometric filter or data set.

        Returns
        -------
        ln_L : float
            ln(likelihood) summed over the photometric measurement

        """
        lnL = self.log_likely_photometry_each(
            t, mag_obs, mag_err_obs, filt_idx=filt_idx
        )

        return lnL.sum()

    def log_likely_astrometry_each(self, t, x_obs, y_obs, x_err_obs, y_err_obs, filt_idx=0):
        """
        Get the natural log of the likelihood for the input astrometric data in the
        specified filter or data sets. Note, this function eturns a list and it
        is the full ln(likelihood), including the normalization constant.

        Parameters
        ----------
        t : array_like
            List of times in MJD for the observations.
        x_obs : array_like
            List of relative R.A. astrometric positions on the sky in arcsec.
            Length must match t.
        y_obs : array_like
            List of relative Dec. astrometric positions on the sky in arcsec.
            Length must match t.
        x_err_obs : array_like
            List of relative R.A. astrometric positional errors on the sky in arcsec.
            Length must match t.
        y_err_obs : array_like
            List of relative Dec. astrometric positional errors on the sky in arcsec.
            Length must match t.
        filt_idx : int, optional
            Index of the astrometric filter or data set.

        Returns
        -------
        ln_L : array_like
            List of ln(likelihood) for each astrometric measurement.

        """
        pos_model = self.get_astrometry(t, filt_idx=filt_idx)

        lnL = jax_physics.gaussian_log_likelihood_astrometry_each(
            jnp.asarray(pos_model, dtype=jnp.float64),
            jnp.asarray(x_obs, dtype=jnp.float64),
            jnp.asarray(y_obs, dtype=jnp.float64),
            jnp.asarray(x_err_obs, dtype=jnp.float64),
            jnp.asarray(y_err_obs, dtype=jnp.float64),
        )

        return np.asarray(lnL, dtype=np.float64)

    def log_likely_astrometry(self, t, x_obs, y_obs, x_err_obs, y_err_obs, filt_idx=0):
        """
        Get the natural log of the likelihood for the input astrometric data in the
        specified filter or data sets. Note, this function eturns a list and it
        is the full ln(likelihood), including the normalization constant.

        Parameters
        ----------
        t : array_like
            List of times in MJD for the observations.
        x_obs : array_like
            List of relative R.A. astrometric positions on the sky in arcsec.
            Length must match t.
        y_obs : array_like
            List of relative Dec. astrometric positions on the sky in arcsec.
            Length must match t.
        x_err_obs : array_like
            List of relative R.A. astrometric positional errors on the sky in arcsec.
            Length must match t.
        y_err_obs : array_like
            List of relative Dec. astrometric positional errors on the sky in arcsec.
            Length must match t.
        filt_idx : int, optional
            Index of the astrometric filter or data set.

        Returns
        -------
        ln_L : array_like
            List of ln(likelihood) for each astrometric measurement.

        """
        lnL = self.log_likely_astrometry_each(
            t, x_obs, y_obs, x_err_obs, y_err_obs, filt_idx=filt_idx
        )

        return lnL.sum()

    def animate(self, tE, time_steps, frame_time, name, size, zoom,
                astrometry, filt_idx=0):
        """ Produces animation of microlensing event.

        Parameters
        ----------

        tE:
            number of einstein crossings times before/after the peak you want the animation to plot
                e.g tE = 2 => graph will go from -2 tE to 2 tE
        time_steps:
            number of time steps before/after peak, so total number of time steps will
            be 2 times this value
        frame_time:
            times in ms of each frame in the animation
        name: string
            the animation will be saved as name.html
        size: list
            [horizontal, vertical] cm's
        zoom:
            # of einstein radii plotted in vertical direction
        """
        times = np.array(range(-time_steps, time_steps + 1, 1))
        tau = tE * times / (-times[0])
        t = self.t0 + (tau * self.tE)

        A = self.get_amplification(t, filt_idx=filt_idx)
        rA = self.get_resolved_amplification(t, filt_idx=filt_idx)
        aplus = rA[:, 0, 0]
        aminus = rA[:, 0, 1]
        rs = self.get_source_astrometry_unlensed(t, filt_idx=filt_idx)
        ri = self.get_resolved_astrometry(t, filt_idx=filt_idx)
        plus = ri[:, 0, 0]
        minus = ri[:, 0, 1]
        l = self.get_lens_astrometry(t, filt_idx=filt_idx)

        # Setup the alpha for the lensed source images.
        aplus_alpha = (0.5 * (aplus - 1) / (aplus.max() - 1)) + 0.5
        aminus_alpha = (0.5 * (aminus - 1) / (aplus.max() - 1)) + 0.5

        fig = plt.figure(figsize=[size[0], size[1] + 0.5])  # sets up the figure
        ax1 = fig.add_subplot(2, 1, 1)
        ax2 = fig.add_subplot(2, 1, 2)
        fig.subplots_adjust(hspace=.5)

        s_line1, = ax1.plot([], '.', markersize=size[0] * 1.3, label="Source",
                            color='gold', linewidth=2)
        s_line2, = ax1.plot([], '-', markersize=size[0] * 0.3,
                            color='gold', linewidth=2)
        l_line1, = ax1.plot([], '.', markersize=size[0] * 1.3, label="Lens",
                            color='black', linewidth=2)
        l_line2, = ax1.plot([], '-', markersize=size[0] * 0.3,
                            color='black', linewidth=2)
        p_line1, = ax1.plot([], '.', markersize=size[0] * 1.3, label="Lensed Source Images",
                            color='coral', linewidth=2)
        p_line2, = ax1.plot([], '-', markersize=size[0] * 0.3,
                            color='coral', linewidth=2)
        m_line1, = ax1.plot([], '.', markersize=size[0] * 1.3,
                            color='coral', linewidth=2)
        m_line2, = ax1.plot([], '-', markersize=size[0] * 0.3,
                            color='coral', linewidth=2)

        dec_lim = 1.1 * np.max(np.abs(np.append(plus[:, 1], minus[:, 1])))
        ax1.set_xlabel('RA (")')
        ax1.set_ylabel('Dec (")')
        ax1.set_xlim(
            (l[0][0] + l[-1][0]) / 2 - 2 * (size[0]) / (2 * size[1]) * (
                    l[-1][1] - l[0][
                1] + 2 * zoom * self.thetaE_amp * 1e-3),
            (l[0][0] + l[-1][0]) / 2 + 2 * (size[0]) / (2 * size[1]) * (
                    l[-1][1] - l[0][
                1] + 2 * zoom * self.thetaE_amp * 1e-3))
        # ax1.set_ylim(l[0][1] - zoom*self.thetaE_amp*0.001, l[-1][1] + zoom*self.thetaE_amp*0.001)
        ax1.set_ylim(-dec_lim, dec_lim)

        title_fmt = r'm$_L$={0:.1f} M$_\odot$, d$_L$={1:.0f} pc, d$_S$={2:.0f} pc '
        title_fmt += r'$\theta_E$={3:.1f} mas, t$_E$={4:.0f} days'
        ax1.set_title(title_fmt.format(self.mL, self.dL, self.dS,
                                       self.thetaE_amp, self.tE), fontsize=12)

        if astrometry == "yes":
            a = self.get_astrometry(t, filt_idx=filt_idx)
            u_line1, = ax1.plot([], '.', markersize=size[0] * 1.3,
                                color='red', linewidth=2,
                                label="Unresolved Astrometry")
            u_line2, = ax1.plot([], '-', markersize=size[0] * 0.3,
                                color='red', linewidth=2)
            mag_line, = ax2.plot(tau, A, color='red', linewidth=2)
            ax1.legend(fontsize=12, loc='upper right')
            ax2.set_xlabel("Time (tE)")
            ax2.set_ylabel("Magnification")

            line = [s_line1, s_line2, l_line1, l_line2,
                    p_line1, p_line2, m_line1, m_line2,
                    u_line1, u_line2, mag_line]

            def update(i, source, lens, plus, minus, astrometry, tau,
                       magnification, line):
                # print(str(i) + ", ", end='', flush=True)
                line[0].set_data([source[i, 0]], [source[i, 1]])
                line[1].set_data(source[:i + 1, 0], source[:i + 1, 1])
                line[2].set_data([lens[i, 0]], [lens[i, 1]])
                line[3].set_data(lens[:i + 1, 0], lens[:i + 1, 1])
                line[4].set_data([plus[i, 0]], [plus[i, 1]])
                line[5].set_data(plus[:i + 1, 0], plus[:i + 1, 1])
                line[6].set_data([minus[i, 0]], [minus[i, 1]])
                line[7].set_data(minus[:i + 1, 0], minus[:i + 1, 1])
                line[8].set_data([astrometry[i, 0]], [astrometry[i, 1]])
                line[9].set_data(astrometry[:i + 1, 0], astrometry[:i + 1, 1])
                line[10].set_data(tau[:i + 1], magnification[:i + 1])
                return line

            """
            FuncAnimation takes in the following arguments

            fig = background figure

            update = function that is called every frame

            len(tau) = the number of frames, so now the first argument passed 
                into update (i) will be (0,1,2...len(tau))

            fargs specifies the other arguments to pass into update

            blit being true means that each frame, if there are elements of it 
                that don't change from the last frame,
                it won't replot them, so this makes it faster

            interval = number of milliseconds between each frame
            alternatively you can specify fps in save after after the file name

            """
            ani = animation.FuncAnimation(fig, update, len(tau),
                                          fargs=[rs, l, plus, minus, a, tau, A, line],
                                          blit=True, interval=frame_time)
            ani.save("%s.mp4" % name, writer="ffmpeg")
        elif astrometry == "no":
            line5, = ax2.plot(tau, A, color='red', linewidth=2)
            ax1.legend()
            ax2.set_xlabel("time(tE)")
            ax2.set_ylabel("Magnification")

            line = [line1, line2, line3, line4, line5]

            def update(i, source, lens, plus, minus, tau, magnification, line):
                print(i)
                line[0].set_data(rs[i][0], rs[i][1])
                line[1].set_data(l[i][0], l[i][1])
                line[2].set_data(plus[i][0], plus[i][1])
                line[3].set_data(minus[i][0], minus[i][1])
                line[4].set_data(tau[:i], magnification[:i])

                return line

            ani = animation.FuncAnimation(fig, update, len(tau),
                                          fargs=[rs, l, plus, minus, tau, A,
                                                 line],
                                          blit=True, interval=frame_time)
            ani.save("%s.mp4" % name, writer="ffmpeg")
        else:
            print("Please enter yes or no, for the final argument")

        return ani


class PSPL_Phot(PSPL):
    """
    Contains methods for model a PSPL photometry only.
    This is a Data-type class in our hierarchy. It is abstract and should not
    be instantiated.

    Attributes
    ----------
    Available class variables that should be defined.

    t0
    tE
    u0_amp
    u0_E
    u0_N
    piE_E - valid only if parallax model
    piE_N - valid only if parallax model
    piE_amp
    b_sff[#]
    mag_src[#] -- add in
    mag_base[#] -- add in
    raL - if parallax model
    decL - if parallax model
    """
    photometryFlag = True
    astrometryFlag = False

    def get_lens_astrometry(self, t, filt_idx=0):
        """Get the lens astrometry.
        In photometry-only coordinates, lens is at the origin.

        Parameters
        ----------
        t : array_like
            Time (in MJD).
        filt_idx : int, optional
            Index of the astrometric filter or data set.

        Returns
        -------
        xL : numpy array, shape=[len(t), 2]
            Position of the lens on sky, in Einstein radius units.
            Always zero.
        """
        return np.zeros((len(t), 2), dtype=float)

    def get_source_astrometry_unlensed(self, t, filt_idx=0):
        """Get the unlensed astrometry of the source.
        Note, this is a photometry only model, so units are in Einstein radii.

        Parameters
        ----------
        t : array_like
            Time (in MJD).
        filt_idx : int, optional
            Index of the astrometric filter or data set.

        Returns
        -------
        xS_unlensed : numpy array, dtype=float, shape = len(t) x 2
            The unlensed positions of the source in Einstein radii (i.e. \\vec{u})
        """
        u = self.get_u(t, filt_idx=filt_idx)

        return u

    def get_astrometry_unlensed(self, t, filt_idx=0):
        """Get the astrometry of the source+lens if the lens didn't exist.
        Note, this is a photometry only model, so units are in Einstein radii.

        Parameters
        ----------
        t : array_like
            Time (in MJD).
        filt_idx : int, optional
            Index of the astrometric filter or data set.

        Returns
        -------
        xS_unlensed : numpy array, dtype=float, shape = len(t) x 2
            The unlensed positions of the source in Einstein radii.
        """
        # Flux-weighted centroid of just the sources.
        u_unlens = self.get_source_astrometry_unlensed(t, filt_idx=filt_idx)

        # Lens is at the origin. Clip a negative lens flux (b_sff > 1)
        # so the source flux fraction becomes 1 instead of extrapolating.
        src_flux_frac = astrometric_source_flux_fraction(self.b_sff[filt_idx])
        pos_unlensed = src_flux_frac * u_unlens

        return pos_unlensed

    def get_resolved_astrometry(self, t, filt_idx=0):
        """
        Position of the observed source position in Einstein radii.

        Parameters
        ----------
        t : array_like, shape = [N_times]
            Array of times to model.
        filt_idx : int, optional
            Index of the astrometric filter or data set.

        Returns
        -------
        model_pos : array_like. shape = [N_times, N_sources, N_images, 2]
            Array of vector positions of the centroid at each t.
        """
        u_vec = self.get_u(t, filt_idx=filt_idx)

        # Separation amplitude and unit vector.
        u = np.linalg.norm(u_vec, axis=1)
        u_hat = (u_vec.T / u).T

        # Plus / minus image positions in Einstein radii.
        u_plus = ((u + np.sqrt(u ** 2 + 4)) / 2.0).reshape(u.size, 1) * u_hat
        u_minu = ((u - np.sqrt(u ** 2 + 4)) / 2.0).reshape(u.size, 1) * u_hat

        u_lensed = np.zeros((len(t), 1, 2, 2), dtype=float)
        u_lensed[:, 0, 0, :] = u_plus
        u_lensed[:, 0, 1, :] = u_minu

        return u_lensed

    def get_astrometry(self, t, filt_idx=0):
        """
        Position of the observed (unresolved) source position in Einstein radii.

        Parameters
        ----------
        t: array_like
            Array of times to model.
        filt_idx : int, optional
            Index of the astrometric filter or data set.

        Returns
        -------
        model_pos : array_like
            Array of vector positions of the centroid at each t.
        """
        # Source magnitude (supports mag_src_pri / mag_src layouts).
        mag_src = self._mag_src_for_jax(filt_idx)
        if mag_src is None:
            if hasattr(self, 'mag_src_pri'):
                mag_src = float(np.asarray(self.mag_src_pri).reshape(-1)[filt_idx])
            else:
                mag_src = float(np.asarray(self.mag_src).reshape(-1)[filt_idx])

        b_sff = self._phot_scalar("b_sff", filt_idx, default=1.0)
        pvec = self._parallax_vectors_for_jax(t, filt_idx)

        # Flux-weighted Einstein-radius centroid including blend.
        u_cent = jax_physics.pspl_phot_astrometry(
            jnp.asarray(t, dtype=jnp.float64).reshape(-1),
            jnp.asarray(self.t0, dtype=jnp.float64),
            jnp.asarray(self.tE, dtype=jnp.float64),
            jnp.asarray(self.u0, dtype=jnp.float64),
            jnp.asarray(self.thetaE_hat, dtype=jnp.float64),
            mag_src,
            b_sff,
            parallax_vectors=pvec,
            piE_E=jnp.asarray(self.piE[0], dtype=jnp.float64),
            piE_N=jnp.asarray(self.piE[1], dtype=jnp.float64),
        )

        return np.asarray(u_cent, dtype=np.float64)

    def get_centroid_shift(self, t, filt_idx=0):
        raise RuntimeError(
            "Astrometry is not supported on this object: " +
            str(self.__class__))

    def log_likely_astrometry(self, t, x, y, xerr, yerr, filt_idx=0):
        raise RuntimeError(
            "Astrometry is not supported on this object: " +
            str(self.__class__))


class PSPL_PhotAstrom(PSPL):
    """
    Contains methods for model a PSPL photometry + astrometry.
    This is a Data-type class in our hierarchy. It is abstract and should not
    be instantiated.

    Attributes
    ----------
    Available class variables that should be defined.

    t0
    tE
    u0_amp
    u0_E
    u0_N
    beta
    piE_E - valid only if parallax model
    piE_N - valid only if parallax model
    piE_amp
    mL
    thetaE_amp
    thetaE_E
    thetaE_N
    xS0_E
    xS0_N
    xL0_E
    xL0_N
    muS_E
    muS_N
    muL_E
    muL_N
    muRel_E
    muRel_N
    muRel_amp
    piS
    piL
    dL
    dS
    dL_dS (dL over dS)
    b_sff[#]
    mag_src[#] -- add in
    mag_base[#] -- add in
    raL - if parallax model
    decL - if parallax model

    """
    photometryFlag = True
    astrometryFlag = True

    def get_lnL_constant(self, err_obs):
        """
        Get the natural log of the constant normalization terms of the likelihood.

        .. math:: -0.5 * \\ln{2 \\pi \\sigma_{obs}^2}

        Parameters
        ----------
        err_obs : array_like
            List of the uncertainties.

        Returns
        -------
        List of ln(likelihood constants).

        """
        lnL_const = -0.5 * np.log(2.0 * math.pi * err_obs ** 2)

        return lnL_const


