        #ap1_term = jnp.imag(jnp.conj(z_p) * z_pp) + jnp.imag(jnp.conj(z_p[kp1]) * z_pp[kp1])
        #ap1 = (1.0 / 24.0) * jnp.sum(jnp.where(parabolic_ok, ap1_term * dtheta**3, 0.0))
        #ap2_term = jnp.imag(jnp.conj(delta) * (z_p[kp1] - z_p)) * dtheta
