######################################################
### BINARY FINITE-SOURCE BINARY LENS (BFSBL) ###
######################################################

class BFSBL(BSBL):
    """
    Binary-source finite-source binary-lens models.

    Each source is integrated with :mod:`bagle.fsbl_contour`. Photometry
    and astrometry are the flux-weighted sum of the two sources (plus
    luminous lenses for astrometry).
    """

    amg_tol = 1e-4
    amg_n_init = 64
    amg_max_pts = 1024
    ld_n_nodes = 8

    def limb_gamma_pri(self, filt_idx=0):
        """
        Primary-source Gamma limb-darkening coefficient.

        Parameters
        ----------
        filt_idx : int, optional
            Filter index.

        Returns
        -------
        gamma : float
        """
        return 0.0

    def limb_gamma_sec(self, filt_idx=0):
        """
        Secondary-source Gamma limb-darkening coefficient.

        Parameters
        ----------
        filt_idx : int, optional
            Filter index.

        Returns
        -------
        gamma : float
        """
        return 0.0

    def _bfsbl_rho(self, which='pri'):
        """
        Source radius in Einstein radii.

        Parameters
        ----------
        which : {'pri', 'sec'}

        Returns
        -------
        rho : float
        """
        rad = self.radiusS_pri if which == 'pri' else self.radiusS_sec
        if hasattr(self, 'thetaE_amp'):
            return float(rad) * 1e3 / self.thetaE_amp

        return float(rad)

    def get_all_arrays(self, t, filt_idx=0, check_sols=True, rescale=True):
        """
        Contour centroids and magnifications for both finite sources.

        Parameters
        ----------
        t : array_like
            Times in MJD.
        filt_idx : int, optional
            Filter index.
        check_sols, rescale : bool, optional
            Ignored (kept for BSBL call-signature compatibility).

        Returns
        -------
        images : ndarray, dtype=complex, shape (N_times, 2, 1)
            Combined image centroid of each source, East + i North.
            Arcsec on the sky for astrometric models; Einstein radii
            from the binary origin otherwise.
        amps : ndarray, shape (N_times, 2, 1)
            Total magnification of each source.
        """
        t = np.atleast_1d(np.asarray(t, dtype=float))

        # Lens and source positions in Einstein radii. Astrometric models
        # use absolute sky tracks (get_u would measure from the lens light
        # centroid, not the lens geometric centre).
        if self.astrometryFlag:
            to_e = 1e3 / self.thetaE_amp
            lens_res = np.asarray(
                self.get_resolved_lens_astrometry(t, filt_idx=filt_idx))
            lens1 = lens_res[:, 0] * to_e
            lens2 = lens_res[:, 1] * to_e
            u = np.asarray(self.get_resolved_source_astrometry_unlensed(
                t, filt_idx=filt_idx), dtype=float) * to_e
            m1 = float(self.mLp / self.mL)
            m2 = float(self.mLs / self.mL)
        else:
            lens_res = np.asarray(self.get_resolved_lens_astrometry(t))
            lens1 = lens_res[:, 0]
            lens2 = lens_res[:, 1]
            u = np.asarray(self.get_u(t, filt_idx=filt_idx), dtype=float)
            m1 = float(self.m1)
            m2 = float(self.m2)

        # Shift everything to the binary origin (geometric centre).
        z1_abs = lens1[:, 0] + 1j * lens1[:, 1]
        z2_abs = lens2[:, 0] + 1j * lens2[:, 1]
        z_geo = 0.5 * (z1_abs + z2_abs)
        z1 = z1_abs - z_geo
        z2 = z2_abs - z_geo
        zeta_pri = u[:, 0, 0] + 1j * u[:, 0, 1]
        zeta_sec = u[:, 1, 0] + 1j * u[:, 1, 1]
        if self.astrometryFlag:
            zeta_pri = zeta_pri - z_geo
            zeta_sec = zeta_sec - z_geo

        n_init = int(getattr(self, 'n_outline', self.amg_n_init) or self.amg_n_init)
        n_init = max(n_init, 16)
        rho_pri = self._bfsbl_rho('pri')
        rho_sec = self._bfsbl_rho('sec')
        g_pri = float(self.limb_gamma_pri(filt_idx))
        g_sec = float(self.limb_gamma_sec(filt_idx))

        def one_source(zeta, rho, gamma):
            if gamma == 0:
                return fsbl_contour.adaptive_limb_images_amps(
                    zeta, rho, s=1.0, q=1.0, n_init=n_init, tol=self.amg_tol,
                    max_pts=self.amg_max_pts, z1=z1, z2=z2, m1=m1, m2=m2)
            return fsbl_contour.ld_images_amps(
                zeta, rho, gamma, s=1.0, q=1.0, n_ld=self.ld_n_nodes,
                n_init=n_init, tol=self.amg_tol, max_pts=self.amg_max_pts,
                z1=z1, z2=z2, m1=m1, m2=m2)

        img_pri, amp_pri = one_source(zeta_pri, rho_pri, g_pri)
        img_sec, amp_sec = one_source(zeta_sec, rho_sec, g_sec)

        # Real [source, E/N] centroids and [source] amps.
        images = np.empty((t.size, 2, 2), dtype=float)
        amps = np.empty((t.size, 2), dtype=float)
        images[:, 0, :] = img_pri
        images[:, 1, :] = img_sec
        amps[:, 0] = amp_pri
        amps[:, 1] = amp_sec

        # Convert to sky arcsec for astrometric models.
        if self.astrometryFlag:
            xL0 = self.get_lens_origin_astrometry(t, filt_idx=filt_idx)
            scale = self.thetaE_amp * 1e-3
            images = xL0[:, None, :] + images * scale

        # Complex East + i North with the combined-image axis: [N, 2, 1].
        images = (images[..., 0] + 1j * images[..., 1])[..., np.newaxis]
        amps = amps[..., np.newaxis]

        return images, amps

    def get_amplification(self, t, filt_idx=0, amp_arr=None):
        """
        Flux-weighted total amplification of both sources.

        Parameters
        ----------
        t : array_like
            Times in MJD.
        filt_idx : int, optional
            Filter index.
        amp_arr : array_like, optional
            Amplifications from :meth:`get_all_arrays`, shape ``(N, 2, 1)``.

        Returns
        -------
        A : ndarray, shape (N,)
        """
        if amp_arr is None:
            _img, amp_arr = self.get_all_arrays(t, filt_idx=filt_idx)

        # Total of each source (one combined image).
        amp = np.sum(np.asarray(amp_arr, dtype=float), axis=2)
        f1 = mag2flux(self.mag_src_pri[filt_idx])
        f2 = mag2flux(self.mag_src_sec[filt_idx])

        return (amp[:, 0] * f1 + amp[:, 1] * f2) / (f1 + f2)

    def get_photometry(self, t, filt_idx=0, amp_arr=None):
        """
        Unresolved photometry of both lensed sources with blending.

        Parameters
        ----------
        t : array_like
            Times in MJD.
        filt_idx : int, optional
            Filter index.
        amp_arr : array_like, optional
            Amplifications from :meth:`get_all_arrays`, shape ``(N, 2, 1)``.

        Returns
        -------
        mag_model : ndarray, shape (N,)
        """
        if amp_arr is None:
            _img, amp_arr = self.get_all_arrays(t, filt_idx=filt_idx)

        # Total of each source (one combined image).
        amp = np.sum(np.asarray(amp_arr, dtype=float), axis=2)
        f1 = mag2flux(self.mag_src_pri[filt_idx])
        f2 = mag2flux(self.mag_src_sec[filt_idx])
        flux = f1 * amp[:, 0] + f2 * amp[:, 1]
        try:
            flux += (f1 + f2) * (1.0 - self.b_sff[filt_idx]) / self.b_sff[filt_idx]
        except AttributeError:
            pass

        return flux2mag(flux)

    def get_astrometry(self, t, image_arr=None, amp_arr=None, filt_idx=0):
        """
        Flux-weighted sky centroid of both sources and luminous lenses.

        Parameters
        ----------
        t : array_like
            Times in MJD.
        image_arr : array_like, optional
            Complex images from :meth:`get_all_arrays`, shape ``(N, 2, 1)``.
        amp_arr : array_like, optional
            Amplifications from :meth:`get_all_arrays`, shape ``(N, 2, 1)``.
        filt_idx : int, optional
            Filter index.

        Returns
        -------
        xCentroid : ndarray, shape (N, 2)
            East / North in arcsec (astrometric) or Einstein radii (phot).
        """
        if (image_arr is None) or (amp_arr is None):
            image_arr, amp_arr = self.get_all_arrays(t, filt_idx=filt_idx)

        # Combined image of each source: [N_times, 2, [E, N]].
        images = _complex_to_vec(image_arr)[:, :, 0, :]
        amp = np.sum(np.asarray(amp_arr, dtype=float), axis=2)
        f1 = mag2flux(self.mag_src_pri[filt_idx])
        f2 = mag2flux(self.mag_src_sec[filt_idx])
        fS = np.stack([f1 * amp[:, 0], f2 * amp[:, 1]], axis=1)

        if self.astrometryFlag:
            _xL = self.get_resolved_lens_astrometry(t, filt_idx=filt_idx)
            xL1, xL2 = _xL[:, 0], _xL[:, 1]
            fL1, fL2 = resolved_lens_fluxes_for_astrometry(
                f1 + f2, self.b_sff[filt_idx], self.dmag_Lp_Ls[filt_idx])
            numer = (images[:, 0] * fS[:, 0:1] + images[:, 1] * fS[:, 1:2]
                     + xL1 * fL1 + xL2 * fL2)
            denom = fS[:, 0] + fS[:, 1] + fL1 + fL2
        else:
            numer = images[:, 0] * fS[:, 0:1] + images[:, 1] * fS[:, 1:2]
            denom = fS[:, 0] + fS[:, 1]

        return numer / denom[:, None]


class BFSBL_Phot(BFSBL, BSBL_Phot):
    """Data class: BFSBL photometry only."""
    photometryFlag = True
    astrometryFlag = False


class BFSBL_PhotAstrom(BFSBL, BSBL_PhotAstrom):
    """Data class: BFSBL photometry + astrometry."""
    photometryFlag = True
    astrometryFlag = True


class BFSBL_noParallax(PSPL_noParallax):
    parallaxFlag = False


class BFSBL_Parallax(PSPL_Parallax):
    parallaxFlag = True


class BFSBL_Limb(BFSBL):
    """
    Linear limb-darkened BFSBL mixin (Gamma law per source and filter).

    Each source has its own per-filter coefficient ``gamma_pri`` /
    ``gamma_sec``. Magnifications and centroids follow
    :func:`bagle.fsbl_contour.ld_images_amps` for each source.
    """

    def limb_gamma_pri(self, filt_idx=0):
        """
        Primary-source linear limb-darkening coefficient for a filter.

        Parameters
        ----------
        filt_idx : int, optional
            Index of the filter or data set.

        Returns
        -------
        gamma : float
            The per-filter ``gamma_pri`` parameter.
        """
        return self.gamma_pri[filt_idx]

    def limb_gamma_sec(self, filt_idx=0):
        """
        Secondary-source linear limb-darkening coefficient for a filter.

        Parameters
        ----------
        filt_idx : int, optional
            Index of the filter or data set.

        Returns
        -------
        gamma : float
            The per-filter ``gamma_sec`` parameter.
        """
        return self.gamma_sec[filt_idx]


class BFSBL_Limb_Phot(BFSBL_Limb, BFSBL_Phot):
    """Data class: limb-darkened BFSBL photometry only."""
    photometryFlag = True
    astrometryFlag = False


class BFSBL_Limb_PhotAstrom(BFSBL_Limb, BFSBL_PhotAstrom):
    """Data class: limb-darkened BFSBL photometry + astrometry."""
    photometryFlag = True
    astrometryFlag = True


class BFSBL_Limb_noParallax(BFSBL_noParallax):
    parallaxFlag = False


class BFSBL_Limb_Parallax(BFSBL_Parallax):
    parallaxFlag = True


class BFSBL_PhotAstromParam1(BSBL_PhotAstromParam1):
    """
    Binary-source FSBL model for photometry and astrometry.

    Same as :class:`BSBL_PhotAstromParam1`, but each source is a uniform finite disk
    integrated with :mod:`bagle.fsbl_contour`. Parameters not listed here are documented
    in :class:`BSBL_PhotAstromParam1`.

    Parameters
    ----------
    radiusS_pri : float
        Angular radius of the primary source on the sky (arcsec). Converted to Einstein
        radii with ``thetaE`` for the finite-source integrals.
    radiusS_sec : float
        Angular radius of the secondary source on the sky (arcsec). Converted to
        Einstein radii with ``thetaE`` for the finite-source integrals.

    See Also
    --------
    BFSBL : Finite-source integration for both sources.
    """
    fitter_param_names = (BSBL_PhotAstromParam1.fitter_param_names
                          + ['radiusS_pri', 'radiusS_sec'])
    filt_param_names = BSBL_PhotAstromParam1.filt_param_names
    filt_param_usage = BSBL_PhotAstromParam1.filt_param_usage

    @classmethod
    def _jax_bfsbl_args(cls, vec, parallax_vectors=None, n_outline=None):
        """
        Traced BFSBL Param1 forward-model arguments from a packed vector.

        Parameters
        ----------
        vec : array_like, float, shape = (N_params,)
            Filter-local vector in ``fitter_param_names`` order.
        parallax_vectors : array_like, float, shape = (N_times, 2), optional
            Precomputed parallax table (parallax classes only).
        n_outline : int or None, optional
            Initial limb samples per disk (static).

        Returns
        -------
        p : dict
            Named parameters.
        args : tuple
            Positional ``(t0, xS0, dxS, xL0, muS, muL, thetaE_amp,
            xL1_over_theta, xL2_over_theta, m1, m2, rho_pri, rho_sec)`` for
            :mod:`bagle.jax.bfs`.
        kw : dict
            Limb darkening, parallax and limb-sampling keywords.
        """
        from bagle.jax.bfs import binary_source_offset
        from bagle.jax.geometry import derive_psbl_photastrom_param1

        p = dict(zip(cls.fitter_param_names, jnp.asarray(vec)))

        # Lens and primary-source geometry, as for PSBL Param1.
        (_, _, _, _, _, xS0, xL0, muS, muL, thetaE, piS, piL, m1,
         m2, xL1, xL2, _, _) = derive_psbl_photastrom_param1(
            p['mLp'], p['mLs'], p['t0'], p['xS0_E'], p['xS0_N'], p['beta'],
            p['muL_E'], p['muL_N'], p['muS_E'], p['muS_N'], p['dL'], p['dS'],
            p['sepL'], p['alphaL'])

        # Secondary source: fixed sky offset from the primary.
        dxS = binary_source_offset(p['sepS'], p['alphaS'])

        # Source radii arcsec -> Einstein radii.
        rho_pri = p['radiusS_pri'] * 1e3 / thetaE
        rho_sec = p['radiusS_sec'] * 1e3 / thetaE

        args = (p['t0'], xS0, dxS, xL0, muS, muL, thetaE, xL1, xL2, m1, m2,
                rho_pri, rho_sec)
        kw = dict(gamma_pri=p.get('gamma_pri'), gamma_sec=p.get('gamma_sec'),
                  parallax_vectors=parallax_vectors, piS=piS, piL=piL,
                  n_outline=n_outline)

        return p, args, kw

    @classmethod
    def jax_log_likely_photometry(cls, vec, t, mag_obs, mag_err, b_sff,
                                  mag_src, parallax_vectors=None,
                                  gp_params=None, fixed_jitter=True,
                                  n_outline=None):
        """
        Traced BFSBL photometric log-likelihood.

        Parameters
        ----------
        vec : array_like, float, shape = (N_params,)
            Filter-local vector in ``fitter_param_names`` order.
        t, mag_obs, mag_err : array_like, float, shape = (N_times,)
            Times (MJD) and photometry.
        b_sff : float
            Filter-local source flux fraction.
        mag_src : tuple of float or None
            ``(mag_src_pri, mag_src_sec)`` from the fitter; ``None`` reads
            both from ``vec``.
        parallax_vectors : array_like, float, shape = (N_times, 2), optional
            Precomputed parallax table (parallax classes only).
        gp_params, fixed_jitter : optional
            GP likelihood inputs (unused by these classes).
        n_outline : int or None, optional
            Initial limb samples per disk (static).

        Returns
        -------
        lnL : float
            Summed photometric log-likelihood.
        """
        from bagle.jax.bfs import bfsbl_log_likely_photometry

        p, args, kw = cls._jax_bfsbl_args(vec, parallax_vectors, n_outline)

        # Source magnitudes from the fitter tuple or the class vector.
        if isinstance(mag_src, (tuple, list)):
            mag_pri, mag_sec = mag_src
        else:
            mag_pri, mag_sec = p['mag_src_pri'], p['mag_src_sec']

        return bfsbl_log_likely_photometry(
            t, *args, mag_pri, mag_sec, b_sff, mag_obs, mag_err,
            gp_params=gp_params, fixed_jitter=fixed_jitter, **kw)

    @classmethod
    def jax_log_likely_astrometry(cls, vec, t, x_obs, y_obs, x_err, y_err,
                                  b_sff=1.0, dmag_Lp_Ls=None,
                                  parallax_vectors=None, n_outline=None):
        """
        Traced BFSBL astrometric log-likelihood.

        Parameters
        ----------
        vec : array_like, float, shape = (N_params,)
            Filter-local vector in ``fitter_param_names`` order; the source
            magnitudes are read from it.
        t, x_obs, y_obs, x_err, y_err : array_like, float, shape = (N_times,)
            Times (MJD) and East / North astrometry (arcsec).
        b_sff : float, optional
            Filter-local source flux fraction.
        dmag_Lp_Ls : float or None, optional
            Primary-minus-secondary lens magnitude difference; ``None``
            reads it from ``vec``.
        parallax_vectors : array_like, float, shape = (N_times, 2), optional
            Precomputed parallax table (parallax classes only).
        n_outline : int or None, optional
            Initial limb samples per disk (static).

        Returns
        -------
        lnL : float
            Summed astrometric log-likelihood.
        """
        from bagle.jax.bfs import bfsbl_log_likely_astrometry

        p, args, kw = cls._jax_bfsbl_args(vec, parallax_vectors, n_outline)
        if dmag_Lp_Ls is None:
            dmag_Lp_Ls = p['dmag_Lp_Ls']

        return bfsbl_log_likely_astrometry(
            t, *args, p['mag_src_pri'], p['mag_src_sec'], b_sff, x_obs, y_obs,
            x_err, y_err, dmag_Lp_Ls=dmag_Lp_Ls, **kw)

    def __init__(self, mLp, mLs, t0, xS0_E, xS0_N, beta, muL_E, muL_N, muS_E, muS_N, dL,
                 dS, sepL, alphaL, sepS, alphaS, mag_src_pri, mag_src_sec, b_sff,
                 dmag_Lp_Ls, radiusS_pri, radiusS_sec, raL=None, decL=None,
                 obsLocation='earth', root_tol=1e-08):
        """
        Initialize the parent model, then store the source radii.

        Parameters are described in the class docstring.
        """
        super().__init__(mLp, mLs, t0, xS0_E, xS0_N, beta, muL_E, muL_N, muS_E, muS_N,
                         dL, dS, sepL, alphaL, sepS, alphaS, mag_src_pri, mag_src_sec,
                         b_sff, dmag_Lp_Ls, raL=raL, decL=decL, obsLocation=obsLocation,
                         root_tol=root_tol)

        # Finite-source radii; radiusS aliases the primary for shared helpers.
        self.radiusS_pri = radiusS_pri
        self.radiusS_sec = radiusS_sec
        self.radiusS = radiusS_pri
        # Keep an n_outline set by a subclass; default 50 limb samples.
        self.n_outline = getattr(self, 'n_outline', 50)

        return None


